    // Shared memory for tiles of A and B
    __shared__ float tileA[TILE_DIM][TILE_DIM];
    __shared__ float tileB[TILE_DIM][TILE_DIM];

    int row = blockIdx.y * TILE_DIM + threadIdx.y;
    int col = blockIdx.x * TILE_DIM + threadIdx.x;

    float sum = 0.0f;

    for (int tile = 0; tile < (N + TILE_DIM - 1) / TILE_DIM; tile++) {
        // Load tile of A into shared memory
        int loadRow = row;
        int loadCol = tile * TILE_DIM + threadIdx.x;
        if (loadRow < N && loadCol < N) {
            tileA[threadIdx.y][threadIdx.x] = A[loadRow * N + loadCol];
        } else {
            tileA[threadIdx.y][threadIdx.x] = 0.0f;
