            tileB[threadIdx.y][threadIdx.x] = B[loadRow * N + loadCol];
        } else {
            tileB[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot product
        for (int k = 0; k < TILE_DIM; k++) {
            sum += tileA[threadIdx.y][k] * tileB[k][threadIdx.x];
