from torch.utils.cpp_extension import load_inline

# Define CUDA kernel for matrix multiplication with register tiling
matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 32
#define BLOCK_ROWS 8
#define BLOCK_COLS 8

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles of A and B
    __shared__ float tileA[TILE_DIM][TILE_DIM];
    __shared__ float tileB[TILE_DIM][TILE_DIM];

    // Thread index
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Block index
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Starting indices for the tile in global memory
    int aBegin = N * TILE_DIM * by;
    int aEnd = aBegin + N - 1;
    int aStep = TILE_DIM;

    int bBegin = TILE_DIM * bx;
    int bStep = TILE_DIM * N;

    // Each thread computes 4x4 elements of C
    float c[4][4] = {{0.0f}};

    // Loop over tiles
    for (int a = aBegin, b = bBegin; a <= aEnd; a += aStep, b += bStep) {
        // Load tile of A into shared memory
        if (a + tx + N * ty < N * N) {
            tileA[ty][tx] = A[a + tx + N * ty];
        } else {
            tileA[ty][tx] = 0.0f;
        }

        // Load tile of B into shared memory
        if (b + tx + N * ty < N * N) {
            tileB[ty][tx] = B[b + tx + N * ty];
        } else {
            tileB[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot products using registers
        for (int k = 0; k < TILE_DIM; k++) {
            // Preload elements into registers
            float aVal0 = tileA[k][tx];
            float aVal1 = tileA[k][tx + BLOCK_COLS];

            float bVal0 = tileB[ty][k];
            float bVal1 = tileB[ty + BLOCK_ROWS][k];

            // Accumulate products
            c[0][0] += aVal0 * bVal0;
            c[0][1] += aVal0 * bVal1;
            c[1][0] += aVal1 * bVal0;
            c[1][1] += aVal1 * bVal1;

            if (BLOCK_COLS > 4) {
                float aVal2 = tileA[k][tx + 2*BLOCK_COLS];
                float aVal3 = tileA[k][tx + 3*BLOCK_COLS];

                float bVal2 = tileB[ty + 2*BLOCK_ROWS][k];
                float bVal3 = tileB[ty + 3*BLOCK_ROWS][k];

                c[0][2] += aVal0 * bVal2;
                c[0][3] += aVal0 * bVal3;
                c[1][2] += aVal1 * bVal2;
                c[1][3] += aVal1 * bVal3;
                c[2][0] += aVal2 * bVal0;
                c[2][1] += aVal2 * bVal1;
                c[3][0] += aVal3 * bVal0;
                c[3][1] += aVal3 * bVal1;
                c[2][2] += aVal2 * bVal2;
                c[2][3] += aVal2 * bVal3;
                c[3][2] += aVal3 * bVal2;
                c[3][3] += aVal3 * bVal3;
            }
        }

        __syncthreads();
    }

    // Write results to global memory
    int cRow = TILE_DIM * by + ty;
    int cCol = TILE_DIM * bx + tx;

    if (cRow < N && cCol < N) {
        int cIndex = cRow * N + cCol;
        C[cIndex] = c[0][0];

        if (cCol + BLOCK_COLS < N) {
            C[cIndex + BLOCK_COLS] = c[0][1];

            if (cRow + BLOCK_ROWS < N) {
                C[cIndex + BLOCK_ROWS * N] = c[1][0];
                C[cIndex + BLOCK_ROWS * N + BLOCK_COLS] = c[1][1];

                if (BLOCK_COLS > 4) {
                    C[cIndex + 2*BLOCK_COLS] = c[0][2];
                    C[cIndex + 3*BLOCK_COLS] = c[0][3];

                    C[cIndex + BLOCK_ROWS * N + 2*BLOCK_COLS] = c[1][2];
                    C[cIndex + BLOCK_ROWS * N + 3*BLOCK_COLS] = c[1][3];

                    C[cIndex + 2*BLOCK_ROWS * N] = c[2][0];
                    C[cIndex + 2*BLOCK_ROWS * N + BLOCK_COLS] = c[2][1];
                    C[cIndex + 2*BLOCK_ROWS * N + 2*BLOCK_COLS] = c[2][2];
                    C[cIndex + 2*BLOCK_ROWS * N + 3*BLOCK_COLS] = c[2][3];

                    C[cIndex + 3*BLOCK_ROWS * N] = c[3][0];
                    C[cIndex + 3*BLOCK_ROWS * N + BLOCK_COLS] = c[3][1];
                    C[cIndex + 3*BLOCK_ROWS * N + 2*BLOCK_COLS] = c[3][2];
                    C[cIndex + 3*BLOCK_ROWS * N + 3*BLOCK_COLS] = c[3][3];
                }
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 threadsPerBlock(BLOCK_COLS, BLOCK_ROWS);
    dim3 numBlocks((N + TILE_DIM - 1) / TILE_DIM, 
                   (N + TILE_DIM - 1) / TILE_DIM);

    matmul_kernel<<<numBlocks, threadsPerBlock>>>(A.data_ptr<float>(), 
                                                B.data_ptr<float>(), 
                                                C.data_ptr<float>(), 
                                                N);

    return C;
}
"""

